287	impl Savepoint<'_> {
288	    #[inline]
289	    fn with_name_<T: Into<String>>(conn: &Connection, name: T) -> Result<Savepoint<'_>> {
290	        let name = name.into();
291	        let sql = cmd("SAVEPOINT", false, name.as_str())?;
292	        // A savepoint created outside of any transaction begins one, so its
293	        // release commits the whole transaction.
294	        let starts_transaction = conn.is_autocommit();
295	        conn.execute_batch(sql.as_str()).map(|()| Savepoint {
296	            conn,
297	            name,
298	            drop_behavior: DropBehavior::Rollback,
299	            committed: false,
300	            starts_transaction,
301	        })
302	    }
303	
304	    #[inline]
305	    fn new_(conn: &Connection) -> Result<Savepoint<'_>> {
306	        Savepoint::with_name_(conn, "_rusqlite_sp")
307	    }
