445	fn cmd(cmd: &'static str, to: bool, name: &str) -> Result<Sql> {
446	    let mut sql = Sql::new();
447	    sql.push_keyword(cmd)?;
448	    sql.push_space();
449	    if to {
450	        sql.push_keyword("TO")?;
451	        sql.push_space();
452	    }
453	    sql.push_identifier(name);
454	    Ok(sql)
455	}
