582	    ///
583	    ///     do_queries_part_1(&sp)?; // sp causes rollback if this fails
584	    ///     do_queries_part_2(&sp)?; // sp causes rollback if this fails
585	    ///
586	    ///     sp.commit()
587	    /// }
588	    /// ```
